    Need(!part?(saved==0&&f.Get_TimeStep()==0):(completed>previous&&completed<=steps),"Actual saved Step is not strictly increasing");for(unsigned j=previous;j<completed;j++)scalar+=dt;previous=completed;const double time=f.Get_TimeStep(),errorClock=std::abs(time-scalar);Need(std::isfinite(time)&&errorClock<=1e-14,"Native scalar += dt clock differs");maxClock=(std::max)(maxClock,errorClock);
