    if(dynamic){Put(raw,layout,part,"PoroVolumeRatio","float64",1,J,order);Put(raw,layout,part,"PoroPorosity","float64",1,por,order);Put(raw,layout,part,"PoroThetaLastStage","float64",1,theta,order);Put(raw,layout,part,"PoroCurrentVolume","float64",1,V,order);Put(raw,layout,part,"PoroMixtureDensity","float64",1,mix,order);Put(raw,layout,part,"PoroHydraulicConductivity","float64",1,k,order);Put(raw,layout,part,"PosDiv","float32",1,div,order);}
